import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.CPzUcv0I.js";const c=JSON.parse('{"title":"Installation Multi-Plateforme","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/players/installation.md","filePath":"fr/guide/players/installation.md"}'),n={name:"fr/guide/players/installation.md"};function l(r,e,o,p,h,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation-multi-plateforme" tabindex="-1">Installation Multi-Plateforme <a class="header-anchor" href="#installation-multi-plateforme" aria-label="Permalink to &quot;Installation Multi-Plateforme&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Windows-10%20%2F%2011-blue.svg" alt="Windows"><img src="https://img.shields.io/badge/macOS-Intel%20%26%20Apple%20Silicon-lightgrey.svg" alt="macOS"><img src="https://img.shields.io/badge/Linux-AppImage%20%26%20APT-red.svg" alt="Linux"></div><p>Gens Launcher est disponible nativement sur <strong>Windows</strong>, <strong>macOS</strong> et <strong>Linux</strong>. Suivez les instructions ci-dessous pour installer l&#39;application sur votre système.</p><hr><h2 id="windows-10-et-11" tabindex="-1">Windows (10 et 11) <a class="header-anchor" href="#windows-10-et-11" aria-label="Permalink to &quot;Windows (10 et 11)&quot;">​</a></h2><h3 id="telechargement-et-installation" tabindex="-1">Téléchargement et Installation <a class="header-anchor" href="#telechargement-et-installation" aria-label="Permalink to &quot;Téléchargement et Installation&quot;">​</a></h3><ol><li>Rendez-vous sur les <a href="https://github.com/WilliamBossard/Gens-Launcher/releases/latest" target="_blank" rel="noreferrer">Dernières Releases GitHub</a>.</li><li>Téléchargez le fichier d&#39;installation <strong><code>GensLauncher-Setup-X.X.X.exe</code></strong>.</li><li>Double-cliquez sur le fichier téléchargé pour démarrer l&#39;assistant d&#39;installation NSIS.</li></ol><div class="warning custom-block"><p class="custom-block-title">Avertissement Windows Defender SmartScreen</p><p>Gens Launcher est un projet indépendant open-source. Comme le projet ne possède pas de certificat d&#39;entreprise commercial payant (EV Code Signing, coûtant plusieurs centaines d&#39;euros par an), Windows SmartScreen peut afficher une fenêtre bleue avec le message :<br><em>« Windows a protégé votre ordinateur »</em>.</p><p><strong>Pour continuer :</strong></p><ol><li>Cliquez sur le lien texte <strong>« Informations complémentaires »</strong> (ou <em>« More info »</em>).</li><li>Cliquez sur le bouton <strong>« Exécuter quand même »</strong> (ou <em>« Run anyway »</em>).</li><li>Le code source étant intégralement public et auditable sur GitHub, le lanceur est 100% sûr.</li></ol></div><hr><h2 id="macos-intel-et-apple-silicon" tabindex="-1">macOS (Intel et Apple Silicon) <a class="header-anchor" href="#macos-intel-et-apple-silicon" aria-label="Permalink to &quot;macOS (Intel et Apple Silicon)&quot;">​</a></h2><ol><li>Téléchargez l&#39;image disque <strong><code>GensLauncher-X.X.X-mac.dmg</code></strong> depuis les <a href="https://github.com/WilliamBossard/Gens-Launcher/releases/latest" target="_blank" rel="noreferrer">Releases GitHub</a>.</li><li>Double-cliquez sur le fichier <code>.dmg</code> pour ouvrir le volume d&#39;installation.</li><li>Glissez-déposez l&#39;icône <strong>Gens Launcher</strong> directement dans le dossier <strong>Applications</strong>.</li></ol><div class="danger custom-block"><p class="custom-block-title">Important : Dossier Applications Obligatoire</p><p>Vous devez impérativement copier l&#39;application dans le dossier <code>/Applications</code>. Si vous exécutez le lanceur directement depuis le volume DMG virtuel, le système de mise à jour automatique (Auto-Updater) ne pourra pas fonctionner correctement.</p></div><hr><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>Nous mettons à disposition deux formats de distribution pour Linux :</p><h3 id="option-1-depot-apt-officiel-recommande-pour-debian-et-ubuntu" tabindex="-1">Option 1 : Dépôt APT Officiel (Recommandé pour Debian et Ubuntu) <a class="header-anchor" href="#option-1-depot-apt-officiel-recommande-pour-debian-et-ubuntu" aria-label="Permalink to &quot;Option 1 : Dépôt APT Officiel (Recommandé pour Debian et Ubuntu)&quot;">​</a></h3><p>Cette méthode est la plus pratique : elle intègre Gens Launcher au gestionnaire de paquets de votre système. Les mises à jour s&#39;effectueront automatiquement avec vos commandes de mise à jour habituelles (<code>apt upgrade</code>).</p><p>Ouvrez un terminal et exécutez ces 3 étapes :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Téléchargez et enregistrez la clé de signature publique GPG officielle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://williambossard.github.io/Gens-Launcher/public.key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dearmor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/keyrings/gens-launcher-keyring.gpg</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Ajoutez le dépôt Gens Launcher à vos sources logicielles</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;deb [signed-by=/usr/share/keyrings/gens-launcher-keyring.gpg] https://williambossard.github.io/Gens-Launcher/ ./&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/sources.list.d/gens-launcher.list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Mettez à jour vos dépôts et installez Gens Launcher</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gens-launcher</span></span></code></pre></div><p>Pour mettre à jour le lanceur à l&#39;avenir :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only-upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gens-launcher</span></span></code></pre></div><h3 id="option-2-paquet-universel-appimage" tabindex="-1">Option 2 : Paquet Universel AppImage <a class="header-anchor" href="#option-2-paquet-universel-appimage" aria-label="Permalink to &quot;Option 2 : Paquet Universel AppImage&quot;">​</a></h3><p>Le format AppImage fonctionne sur toutes les distributions Linux modernes (Fedora, Arch Linux, Manjaro, Ubuntu, etc.) sans installation préalable :</p><ol><li>Téléchargez le fichier <strong><code>GensLauncher-X.X.X.AppImage</code></strong>.</li><li>Rendez le fichier exécutable : <ul><li><strong>En ligne de commande :</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GensLauncher-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.AppImage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GensLauncher-*.AppImage</span></span></code></pre></div></li><li><strong>En interface graphique :</strong> Clic droit sur le fichier -&gt; <em>Propriétés</em> -&gt; onglet <em>Permissions</em> -&gt; cochez <em>« Autoriser l&#39;exécution du fichier comme un programme »</em>.</li></ul></li><li>Double-cliquez sur l&#39;AppImage pour jouer !</li></ol><hr><h2 id="configuration-systeme-requise" tabindex="-1">Configuration Système Requise <a class="header-anchor" href="#configuration-systeme-requise" aria-label="Permalink to &quot;Configuration Système Requise&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Composant</th><th>Recommandation Minimale</th><th>Recommandation Optimale</th></tr></thead><tbody><tr><td><strong>Système d&#39;exploitation</strong></td><td>Windows 10 (64-bit), macOS 11+, Linux 64-bit</td><td>Windows 11, macOS 14+, Ubuntu 24.04 LTS</td></tr><tr><td><strong>Mémoire Vive (RAM)</strong></td><td>4 Go de RAM système</td><td>8 à 16 Go de RAM système</td></tr><tr><td><strong>Stockage Libre</strong></td><td>2 Go pour le lanceur et Minecraft</td><td>10+ Go (selon la taille de vos modpacks et shaders)</td></tr><tr><td><strong>Runtime Java</strong></td><td>Java 8, 17 ou 21 (selon version de Minecraft)</td><td><strong>Géré automatiquement par Gens Launcher</strong></td></tr></tbody></table>`,27)])])}const g=s(n,[["render",l]]);export{c as __pageData,g as default};
